'use client'

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Button } from '@/components/ui/button'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import { Skeleton } from '@/components/ui/skeleton'
import { PurchaseOrderForm } from '@/components/inventory/PurchaseOrderForm'
import { PurchaseOrderDetail } from '@/components/inventory/PurchaseOrderDetail'
import { queryKeys } from '@/lib/query-keys'
import { formatCurrency, formatDate } from '@/lib/utils'
import { toast } from 'sonner'
import {
  Plus,
  ShoppingCart,
  MoreHorizontal,
  Eye,
  Pencil,
  CheckCircle,
  XCircle,
} from 'lucide-react'
import type { PurchaseOrder, Supplier } from '@/lib/supabase/types'

type POWithRelations = PurchaseOrder & {
  suppliers: Pick<Supplier, 'id' | 'name'> | null
  line_count?: number
}

type POStatus = PurchaseOrder['status']

const STATUS_CONFIG: Record<
  POStatus,
  { label: string; classes: string }
> = {
  draft: {
    label: 'Draft',
    classes: 'bg-transparent text-[color:var(--color-stone)] border border-[color:var(--color-stone)]/40',
  },
  ordered: {
    label: 'Ordered',
    classes: 'bg-muted text-stone-brand border border-stone-brand/30',
  },
  partial: {
    label: 'Partial',
    classes: 'bg-transparent text-[color:var(--color-rust)] border border-[color:var(--color-rust)]/50',
  },
  received: {
    label: 'Received',
    classes: 'bg-muted text-foreground border border-border/60',
  },
  cancelled: {
    label: 'Cancelled',
    classes: 'bg-transparent text-[color:var(--color-stone)]/50',
  },
} as const

function computeOverdueDays(expectedAt: string | null): number | null {
  if (!expectedAt) return null
  const expected = new Date(expectedAt)
  const now = new Date()
  if (now <= expected) return null
  return Math.floor((now.getTime() - expected.getTime()) / 86400000)
}

function pluralizeItems(count: number): string {
  return count === 1 ? '1 item' : `${count} items`
}

interface CancelConfirmProps {
  po: POWithRelations
  open: boolean
  onOpenChange: (open: boolean) => void
  onConfirm: () => void
  isPending: boolean
}

function CancelConfirmDialog({
  po,
  open,
  onOpenChange,
  onConfirm,
  isPending,
}: CancelConfirmProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent showCloseButton={false}>
        <DialogHeader>
          <DialogTitle>Cancel PO {po.order_number}?</DialogTitle>
          <DialogDescription>
            This can&apos;t be undone. The order will be marked as cancelled.
          </DialogDescription>
        </DialogHeader>
        <DialogFooter>
          <Button
            variant="outline"
            size="sm"
            onClick={() => onOpenChange(false)}
            disabled={isPending}
          >
            Keep order
          </Button>
          <Button
            size="sm"
            className="bg-[color:var(--color-rust)] text-[color:var(--color-bone)] hover:bg-[color:var(--color-rust)]/90"
            onClick={onConfirm}
            disabled={isPending}
          >
            {isPending ? 'Cancelling…' : 'Cancel order'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

export function PurchaseOrdersTable() {
  const queryClient = useQueryClient()
  const [statusFilter, setStatusFilter] = useState('all')
  const [formOpen, setFormOpen] = useState(false)
  const [editId, setEditId] = useState<string | null>(null)
  const [detailId, setDetailId] = useState<string | null>(null)
  const [cancelTarget, setCancelTarget] = useState<POWithRelations | null>(null)

  const { data, isLoading } = useQuery({
    queryKey: queryKeys.inventory.purchaseOrders({ status: statusFilter }),
    queryFn: async () => {
      const params = new URLSearchParams()
      if (statusFilter !== 'all') params.set('status', statusFilter)
      const res = await fetch(`/api/inventory/purchase-orders?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to fetch purchase orders')
      const json = await res.json() as { data: POWithRelations[] }
      return json.data
    },
  })

  const receiveMutation = useMutation({
    mutationFn: async (id: string) => {
      const res = await fetch(`/api/inventory/purchase-orders/${id}/receive`, {
        method: 'POST',
      })
      if (!res.ok) throw new Error('Failed to mark as received')
    },
    onSuccess: () => {
      toast.success('Purchase order marked as received')
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.purchaseOrders() })
    },
    onError: () => toast.error('Failed to mark purchase order as received'),
  })

  const cancelMutation = useMutation({
    mutationFn: async (id: string) => {
      const res = await fetch(`/api/inventory/purchase-orders/${id}/cancel`, {
        method: 'PATCH',
      })
      if (!res.ok) throw new Error('Failed to cancel order')
    },
    onSuccess: () => {
      toast.success('Purchase order cancelled')
      setCancelTarget(null)
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.purchaseOrders() })
    },
    onError: () => toast.error('Failed to cancel purchase order'),
  })

  function handleInvalidate() {
    void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.purchaseOrders() })
  }

  if (isLoading) {
    return (
      <div className="space-y-2">
        {Array.from({ length: 5 }).map((_, i) => (
          <Skeleton key={i} className="h-10 w-full" />
        ))}
      </div>
    )
  }

  const orders = data ?? []

  return (
    <>
      <div className="flex items-center gap-2 justify-between">
        <Select
          value={statusFilter}
          onValueChange={(v) => { if (v !== null) setStatusFilter(v) }}
        >
          <SelectTrigger className="h-8 w-36">
            <SelectValue placeholder="Status" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Orders</SelectItem>
            <SelectItem value="draft">Draft</SelectItem>
            <SelectItem value="ordered">Ordered</SelectItem>
            <SelectItem value="partial">Partial</SelectItem>
            <SelectItem value="received">Received</SelectItem>
            <SelectItem value="cancelled">Cancelled</SelectItem>
          </SelectContent>
        </Select>
        <Button size="sm" onClick={() => { setEditId(null); setFormOpen(true) }}>
          <Plus className="mr-1.5 h-4 w-4" />
          New Order
        </Button>
      </div>

      {orders.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 gap-3">
          <div className="rounded-xl bg-primary/10 p-4">
            <ShoppingCart className="h-8 w-8 text-primary/70" />
          </div>
          <div className="text-center space-y-1">
            <p className="text-sm font-medium">No purchase orders</p>
            <p className="text-xs text-muted-foreground">
              {statusFilter !== 'all'
                ? `No orders with status "${STATUS_CONFIG[statusFilter as POStatus]?.label ?? statusFilter}"`
                : 'Create your first purchase order to track restocking'}
            </p>
          </div>
          {statusFilter === 'all' && (
            <Button
              size="sm"
              variant="outline"
              onClick={() => { setEditId(null); setFormOpen(true) }}
            >
              <Plus className="mr-1.5 h-4 w-4" />
              New Order
            </Button>
          )}
        </div>
      ) : (
        <div className="rounded-lg border border-border overflow-hidden">
          <Table>
            <TableHeader>
              <TableRow className="bg-muted/30 hover:bg-muted/30">
                <TableHead className="text-xs">Order #</TableHead>
                <TableHead className="text-xs">Supplier</TableHead>
                <TableHead className="text-xs">Status</TableHead>
                <TableHead className="text-xs">Items</TableHead>
                <TableHead className="text-xs">Ordered</TableHead>
                <TableHead className="text-xs">Expected</TableHead>
                <TableHead className="text-xs text-right">Total</TableHead>
                <TableHead className="w-10" />
              </TableRow>
            </TableHeader>
            <TableBody>
              {orders.map((po) => {
                const statusCfg = STATUS_CONFIG[po.status]
                const overdueDays =
                  po.status === 'ordered'
                    ? computeOverdueDays(po.expected_delivery_at)
                    : null
                const lineCount = po.line_count ?? 0

                return (
                  <TableRow key={po.id} className="group hover:bg-muted/20">
                    <TableCell>
                      <span className="text-sm font-medium font-mono">{po.order_number}</span>
                    </TableCell>
                    <TableCell>
                      <span className="text-sm text-muted-foreground">
                        {po.suppliers?.name ?? '—'}
                      </span>
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-1.5 flex-wrap">
                        <span
                          className={`inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-medium ${statusCfg.classes}`}
                        >
                          {statusCfg.label}
                        </span>
                        {overdueDays !== null && overdueDays > 0 && (
                          <span className="inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-medium tabular-nums bg-[color:var(--color-rust)] text-[color:var(--color-bone)]">
                            Overdue · {overdueDays}d
                          </span>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      {lineCount > 0 ? (
                        <span className="text-sm font-medium tabular-nums text-foreground">
                          {pluralizeItems(lineCount)} · {formatCurrency(po.total_cents)}
                        </span>
                      ) : (
                        <span className="text-sm text-muted-foreground">—</span>
                      )}
                    </TableCell>
                    <TableCell className="text-xs text-muted-foreground">
                      {po.ordered_at ? formatDate(po.ordered_at) : '—'}
                    </TableCell>
                    <TableCell className="text-xs text-muted-foreground">
                      {po.expected_delivery_at ? formatDate(po.expected_delivery_at) : '—'}
                    </TableCell>
                    <TableCell className="text-right text-sm tabular-nums">
                      {formatCurrency(po.total_cents)}
                    </TableCell>
                    <TableCell>
                      <DropdownMenu>
                        <DropdownMenuTrigger
                          render={
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-7 w-7 opacity-0 group-hover:opacity-100"
                            >
                              <MoreHorizontal className="h-4 w-4" />
                              <span className="sr-only">Actions for {po.order_number}</span>
                            </Button>
                          }
                        />
                        <DropdownMenuContent align="end">
                          {/* View — always */}
                          <DropdownMenuItem onClick={() => setDetailId(po.id)}>
                            <Eye className="mr-2 h-4 w-4" />
                            View
                          </DropdownMenuItem>

                          {/* Edit — draft only */}
                          {po.status === 'draft' && (
                            <DropdownMenuItem
                              onClick={() => {
                                setEditId(po.id)
                                setFormOpen(true)
                              }}
                            >
                              <Pencil className="mr-2 h-4 w-4" />
                              Edit
                            </DropdownMenuItem>
                          )}

                          {/* Mark received — ordered or partial */}
                          {(po.status === 'ordered' || po.status === 'partial') && (
                            <DropdownMenuItem
                              onClick={() => receiveMutation.mutate(po.id)}
                              disabled={receiveMutation.isPending}
                            >
                              <CheckCircle className="mr-2 h-4 w-4" />
                              Mark received
                            </DropdownMenuItem>
                          )}

                          {/* Cancel — draft or ordered */}
                          {(po.status === 'draft' || po.status === 'ordered') && (
                            <>
                              <DropdownMenuSeparator />
                              <DropdownMenuItem
                                variant="destructive"
                                onClick={() => setCancelTarget(po)}
                              >
                                <XCircle className="mr-2 h-4 w-4" />
                                Cancel
                              </DropdownMenuItem>
                            </>
                          )}
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                )
              })}
            </TableBody>
          </Table>
        </div>
      )}

      {/* New PO form */}
      <PurchaseOrderForm
        open={formOpen && editId === null}
        onOpenChange={(open) => {
          setFormOpen(open)
          if (!open) setEditId(null)
        }}
        onSuccess={handleInvalidate}
      />

      {/* Detail drawer */}
      {detailId && (
        <PurchaseOrderDetail
          id={detailId}
          open={true}
          onOpenChange={(open) => { if (!open) setDetailId(null) }}
          onSuccess={handleInvalidate}
        />
      )}

      {/* Cancel confirm dialog */}
      {cancelTarget && (
        <CancelConfirmDialog
          po={cancelTarget}
          open={true}
          onOpenChange={(open) => { if (!open) setCancelTarget(null) }}
          onConfirm={() => cancelMutation.mutate(cancelTarget.id)}
          isPending={cancelMutation.isPending}
        />
      )}
    </>
  )
}

'use client'

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip'
import { Skeleton } from '@/components/ui/skeleton'
import { SupplierForm } from '@/components/inventory/SupplierForm'
import { PurchaseOrderForm } from '@/components/inventory/PurchaseOrderForm'
import { queryKeys } from '@/lib/query-keys'
import { formatCurrency } from '@/lib/utils'
import { toast } from 'sonner'
import { formatDistanceToNow, parseISO } from 'date-fns'
import {
  Plus,
  Search,
  MoreHorizontal,
  Eye,
  Edit,
  ShoppingCart,
  Archive,
  Truck,
} from 'lucide-react'
import type { Supplier } from '@/lib/supabase/types'

type SupplierWithMeta = Supplier & {
  inventory_items: { id: string }[]
  last_ordered_at?: string | null
  ytd_spent_cents?: number | null
}

function humanizeDate(iso: string | null | undefined): string {
  if (!iso) return '—'
  try {
    return formatDistanceToNow(parseISO(iso), { addSuffix: true })
  } catch {
    return '—'
  }
}

function formatIsoDisplay(iso: string | null | undefined): string {
  if (!iso) return ''
  try {
    return new Date(iso).toLocaleDateString(undefined, {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    })
  } catch {
    return ''
  }
}

export function SuppliersTable() {
  const queryClient = useQueryClient()
  const [search, setSearch] = useState('')
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [editSupplier, setEditSupplier] = useState<Supplier | null>(null)
  const [viewSupplier, setViewSupplier] = useState<Supplier | null>(null)
  const [newPOOpen, setNewPOOpen] = useState(false)
  // Pre-filled supplier id for New PO — consumed by PurchaseOrderForm when that prop lands
  const [_prefillSupplierId, setPrefillSupplierId] = useState<string | null>(null)

  const { data, isLoading } = useQuery({
    queryKey: queryKeys.inventory.suppliers(),
    queryFn: async () => {
      const res = await fetch('/api/inventory/suppliers')
      if (!res.ok) throw new Error('Failed to fetch suppliers')
      const json = await res.json() as { data: SupplierWithMeta[] }
      return json.data
    },
  })

  const archiveMutation = useMutation({
    mutationFn: async (id: string) => {
      const res = await fetch(`/api/inventory/suppliers/${id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed to archive supplier')
    },
    onSuccess: () => {
      toast.success('Supplier archived')
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.suppliers() })
    },
    onError: () => toast.error('Failed to archive supplier'),
  })

  const filtered = (data ?? []).filter((s) => {
    if (!search) return true
    const q = search.toLowerCase()
    return s.name.toLowerCase().includes(q) || s.email?.toLowerCase().includes(q)
  })

  if (isLoading) {
    return (
      <div className="space-y-2">
        {Array.from({ length: 5 }).map((_, i) => (
          <Skeleton key={i} className="h-10 w-full" />
        ))}
      </div>
    )
  }

  return (
    <TooltipProvider>
      <>
        <div className="flex items-center gap-2 justify-between">
          <div className="relative max-w-xs flex-1">
            <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Search suppliers..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-8 h-8"
            />
          </div>
          <Button
            size="sm"
            onClick={() => { setEditSupplier(null); setDrawerOpen(true) }}
            className="shrink-0"
          >
            <Plus className="mr-1.5 h-4 w-4" />
            Add Supplier
          </Button>
        </div>

        {filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 gap-3">
            <div className="rounded-xl bg-primary/10 p-4">
              <Truck className="h-8 w-8 text-primary/70" />
            </div>
            <div className="text-center space-y-1">
              <p className="text-sm font-medium">No suppliers found</p>
              <p className="text-xs text-muted-foreground">
                {search ? 'Try adjusting your search' : 'Add your first supplier to track orders'}
              </p>
            </div>
            {!search && (
              <Button
                size="sm"
                variant="outline"
                onClick={() => { setEditSupplier(null); setDrawerOpen(true) }}
              >
                <Plus className="mr-1.5 h-4 w-4" />
                Add Supplier
              </Button>
            )}
          </div>
        ) : (
          <div className="rounded-lg border border-border overflow-hidden">
            <Table>
              <TableHeader>
                <TableRow className="bg-muted/30 hover:bg-muted/30">
                  <TableHead className="text-xs">Name</TableHead>
                  <TableHead className="text-xs">Contact</TableHead>
                  <TableHead className="text-xs">Email</TableHead>
                  <TableHead className="text-xs">Phone</TableHead>
                  <TableHead className="text-xs">Last ordered</TableHead>
                  <TableHead className="text-xs text-right">YTD spent</TableHead>
                  <TableHead className="text-xs text-right">Items</TableHead>
                  <TableHead className="w-10" />
                </TableRow>
              </TableHeader>
              <TableBody>
                {filtered.map((supplier) => {
                  const lastOrderedHuman = humanizeDate(supplier.last_ordered_at)
                  const lastOrderedFull = formatIsoDisplay(supplier.last_ordered_at)
                  const ytd = supplier.ytd_spent_cents ?? 0

                  return (
                    <TableRow key={supplier.id} className="group">
                      <TableCell>
                        <span className="text-sm font-medium">{supplier.name}</span>
                      </TableCell>
                      <TableCell>
                        <span className="text-sm text-muted-foreground">
                          {supplier.contact_name ?? '—'}
                        </span>
                      </TableCell>
                      <TableCell>
                        {supplier.email ? (
                          <a
                            href={`mailto:${supplier.email}`}
                            className="text-sm text-primary hover:underline"
                          >
                            {supplier.email}
                          </a>
                        ) : (
                          <span className="text-sm text-muted-foreground">—</span>
                        )}
                      </TableCell>
                      <TableCell>
                        <span className="text-sm text-muted-foreground">
                          {supplier.phone ?? '—'}
                        </span>
                      </TableCell>

                      {/* Last ordered — humanized with tooltip for full date */}
                      <TableCell>
                        {lastOrderedFull ? (
                          <Tooltip>
                            <TooltipTrigger className="cursor-default">
                              <span className="text-sm text-muted-foreground">
                                {lastOrderedHuman}
                              </span>
                            </TooltipTrigger>
                            <TooltipContent side="top">
                              {lastOrderedFull}
                            </TooltipContent>
                          </Tooltip>
                        ) : (
                          <Tooltip>
                            <TooltipTrigger className="cursor-default">
                              <span className="text-sm text-muted-foreground">—</span>
                            </TooltipTrigger>
                            <TooltipContent side="top">No orders yet</TooltipContent>
                          </Tooltip>
                        )}
                      </TableCell>

                      {/* YTD spent */}
                      <TableCell className="text-right">
                        {ytd > 0 ? (
                          <span className="text-sm font-medium tabular-nums">
                            {formatCurrency(ytd)}
                          </span>
                        ) : (
                          <span className="text-sm text-muted-foreground">—</span>
                        )}
                      </TableCell>

                      <TableCell className="text-right">
                        <span className="text-sm tabular-nums">
                          {supplier.inventory_items?.length ?? 0}
                        </span>
                      </TableCell>

                      <TableCell>
                        <DropdownMenu>
                          <DropdownMenuTrigger
                            render={
                              <Button
                                variant="ghost"
                                size="icon"
                                className="h-7 w-7 opacity-0 group-hover:opacity-100"
                              >
                                <MoreHorizontal className="h-4 w-4" />
                                <span className="sr-only">Actions for {supplier.name}</span>
                              </Button>
                            }
                          />
                          <DropdownMenuContent align="end">
                            {/* View — read-only sheet (opens SupplierForm in edit mode; form shows existing data) */}
                            <DropdownMenuItem
                              onClick={() => {
                                setViewSupplier(supplier)
                                setDrawerOpen(true)
                              }}
                            >
                              <Eye className="mr-2 h-4 w-4" />
                              View
                            </DropdownMenuItem>

                            {/* Edit */}
                            <DropdownMenuItem
                              onClick={() => {
                                setEditSupplier(supplier)
                                setDrawerOpen(true)
                              }}
                            >
                              <Edit className="mr-2 h-4 w-4" />
                              Edit
                            </DropdownMenuItem>

                            {/* New PO with supplier pre-filled */}
                            <DropdownMenuItem
                              onClick={() => {
                                setPrefillSupplierId(supplier.id)
                                setNewPOOpen(true)
                              }}
                            >
                              <ShoppingCart className="mr-2 h-4 w-4" />
                              New PO
                            </DropdownMenuItem>

                            <DropdownMenuSeparator />

                            <DropdownMenuItem
                              variant="destructive"
                              onClick={() => archiveMutation.mutate(supplier.id)}
                            >
                              <Archive className="mr-2 h-4 w-4" />
                              Archive
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  )
                })}
              </TableBody>
            </Table>
          </div>
        )}

        {/* Edit / view supplier form */}
        <SupplierForm
          open={drawerOpen}
          onOpenChange={(open) => {
            setDrawerOpen(open)
            if (!open) {
              setEditSupplier(null)
              setViewSupplier(null)
            }
          }}
          supplier={editSupplier ?? viewSupplier}
          onSuccess={() => {
            void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.suppliers() })
          }}
        />

        {/* New PO form — supplier pre-fill relies on PurchaseOrderForm gaining a supplierId prop */}
        <PurchaseOrderForm
          open={newPOOpen}
          onOpenChange={(open) => {
            setNewPOOpen(open)
            if (!open) setPrefillSupplierId(null)
          }}
          onSuccess={() => {
            void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.suppliers() })
          }}
        />
      </>
    </TooltipProvider>
  )
}

'use client'

import { useState } from 'react'
import { useQuery } from '@tanstack/react-query'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Input } from '@/components/ui/input'
import { Skeleton } from '@/components/ui/skeleton'
import { Button } from '@/components/ui/button'
import { queryKeys } from '@/lib/query-keys'
import { formatDate, cn } from '@/lib/utils'
import { ArrowDown, ArrowUp, PackageOpen, ChevronLeft, ChevronRight } from 'lucide-react'
import type { InventoryMovement } from '@/lib/supabase/types'

type MovementWithRelations = InventoryMovement & {
  inventory_items: { id: string; name: string; unit: string } | null
  profiles: { full_name: string | null } | null
}

const REASON_LABELS: Record<InventoryMovement['reason'], string> = {
  purchase: 'Purchase',
  session_use: 'Session Use',
  adjustment: 'Adjustment',
  waste: 'Waste',
  return: 'Return',
  stocktake: 'Stocktake',
  other: 'Other',
}

const REASON_COLORS: Record<InventoryMovement['reason'], string> = {
  purchase: 'bg-muted text-foreground border border-border/60',
  session_use: 'bg-muted text-foreground border border-border/60',
  adjustment: 'bg-muted text-stone-brand border border-stone-brand/30',
  waste: 'bg-destructive/10 text-destructive',
  return: 'bg-muted text-stone-brand border border-stone-brand/30',
  stocktake: 'bg-muted text-foreground border border-border/60',
  other: 'bg-muted text-muted-foreground',
}

/** Derive the Source label from a movement row. */
function deriveSource(m: MovementWithRelations): string {
  if (m.booking_id !== null) return 'Session use'
  if (m.reason === 'purchase') return 'PO receive'
  if (m.reason === 'session_use') return 'Session use'
  // 'sale' is not in the DB enum; included for forward-compat if added
  if ((m.reason as string) === 'sale') return 'Sale'
  if (m.reason === 'stocktake') return 'Stocktake'
  return 'Manual'
}

type QuickRange = 'today' | '7days' | '30days' | 'custom'

/** Format a Date as yyyy-MM-dd for date inputs. */
function toInputDate(d: Date): string {
  return d.toISOString().slice(0, 10)
}

const PAGE_SIZE = 25

export function MovementsLog() {
  const [reason, setReason] = useState('all')
  const [from, setFrom] = useState('')
  const [to, setTo] = useState('')
  const [page, setPage] = useState(0)
  const [activeRange, setActiveRange] = useState<QuickRange>('custom')

  function applyRange(range: QuickRange) {
    const now = new Date()
    if (range === 'today') {
      const today = toInputDate(now)
      setFrom(today)
      setTo(today)
    } else if (range === '7days') {
      const past = new Date(now)
      past.setDate(past.getDate() - 7)
      setFrom(toInputDate(past))
      setTo(toInputDate(now))
    } else if (range === '30days') {
      const past = new Date(now)
      past.setDate(past.getDate() - 30)
      setFrom(toInputDate(past))
      setTo(toInputDate(now))
    }
    // 'custom' → leave pickers as-is
    setActiveRange(range)
    setPage(0)
  }

  function handleFromChange(value: string) {
    setFrom(value)
    setActiveRange('custom')
    setPage(0)
  }

  function handleToChange(value: string) {
    setTo(value)
    setActiveRange('custom')
    setPage(0)
  }

  const params = new URLSearchParams()
  if (reason !== 'all') params.set('reason', reason)
  if (from) params.set('from', from)
  if (to) params.set('to', to)
  params.set('limit', String(PAGE_SIZE))
  params.set('offset', String(page * PAGE_SIZE))

  const { data, isLoading } = useQuery({
    queryKey: queryKeys.inventory.movements({ reason, from, to, page }),
    queryFn: async () => {
      const res = await fetch(`/api/inventory/movements?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to fetch movements')
      const json = await res.json() as { data: MovementWithRelations[]; count: number }
      return json
    },
  })

  const movements = data?.data ?? []
  const total = data?.count ?? 0
  const hasNext = (page + 1) * PAGE_SIZE < total
  const hasPrev = page > 0

  if (isLoading) {
    return (
      <div className="space-y-2">
        {Array.from({ length: 8 }).map((_, i) => (
          <Skeleton key={i} className="h-10 w-full" />
        ))}
      </div>
    )
  }

  const QUICK_RANGES: { value: QuickRange; label: string }[] = [
    { value: 'today', label: 'Today' },
    { value: '7days', label: '7 days' },
    { value: '30days', label: '30 days' },
    { value: 'custom', label: 'Custom' },
  ]

  return (
    <div className="space-y-4">
      {/* Filters */}
      <div className="flex flex-wrap items-center gap-2">
        <Select value={reason} onValueChange={(v) => { if (v !== null) { setReason(v); setPage(0) } }}>
          <SelectTrigger className="h-8 w-36">
            <SelectValue placeholder="Reason" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Reasons</SelectItem>
            <SelectItem value="purchase">Purchase</SelectItem>
            <SelectItem value="session_use">Session Use</SelectItem>
            <SelectItem value="adjustment">Adjustment</SelectItem>
            <SelectItem value="waste">Waste</SelectItem>
            <SelectItem value="return">Return</SelectItem>
            <SelectItem value="stocktake">Stocktake</SelectItem>
            <SelectItem value="other">Other</SelectItem>
          </SelectContent>
        </Select>

        {/* Quick-range chips */}
        <div
          role="group"
          aria-label="Date range"
          className="flex items-center gap-1"
        >
          {QUICK_RANGES.map((r) => (
            <button
              key={r.value}
              type="button"
              onClick={() => applyRange(r.value)}
              className={cn(
                'inline-flex h-8 items-center rounded-md border px-3 text-xs font-medium transition-colors',
                activeRange === r.value
                  ? 'border-[color:var(--color-onyx)] bg-[color:var(--color-onyx)] text-[color:var(--color-bone)]'
                  : 'border-[color:var(--color-stone)]/40 bg-transparent text-[color:var(--color-stone)] hover:border-[color:var(--color-stone)] hover:text-foreground'
              )}
            >
              {r.label}
            </button>
          ))}
        </div>

        {/* Date inputs — active when Custom or any range chosen */}
        <div className="flex items-center gap-1.5">
          <span className="text-xs text-muted-foreground">From</span>
          <Input
            type="date"
            value={from}
            onChange={(e) => handleFromChange(e.target.value)}
            className="h-8 w-36"
          />
        </div>
        <div className="flex items-center gap-1.5">
          <span className="text-xs text-muted-foreground">To</span>
          <Input
            type="date"
            value={to}
            onChange={(e) => handleToChange(e.target.value)}
            className="h-8 w-36"
          />
        </div>
        {(reason !== 'all' || from || to) && (
          <Button
            variant="ghost"
            size="sm"
            className="h-8 text-xs"
            onClick={() => {
              setReason('all')
              setFrom('')
              setTo('')
              setActiveRange('custom')
              setPage(0)
            }}
          >
            Clear filters
          </Button>
        )}
        <span className="ml-auto text-xs text-muted-foreground">
          {total} movement{total !== 1 ? 's' : ''}
        </span>
      </div>

      {movements.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 gap-3">
          <div className="rounded-xl bg-primary/10 p-4">
            <PackageOpen className="h-8 w-8 text-primary/70" />
          </div>
          <div className="text-center space-y-1">
            <p className="text-sm font-medium">No movements recorded</p>
            <p className="text-xs text-muted-foreground">
              Stock changes will appear here as a read-only audit log
            </p>
          </div>
        </div>
      ) : (
        <>
          <div className="rounded-lg border border-border overflow-hidden">
            <Table>
              <TableHeader>
                <TableRow className="bg-muted/30 hover:bg-muted/30">
                  <TableHead className="text-xs">Date</TableHead>
                  <TableHead className="text-xs">Item</TableHead>
                  <TableHead className="text-xs text-right">Delta</TableHead>
                  <TableHead className="text-xs text-right">After</TableHead>
                  <TableHead className="text-xs">Reason</TableHead>
                  <TableHead className="text-xs">Source</TableHead>
                  <TableHead className="text-xs">By</TableHead>
                  <TableHead className="text-xs">Notes</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {movements.map((m) => {
                  const isPositive = m.qty_delta > 0
                  const source = deriveSource(m)

                  return (
                    <TableRow key={m.id}>
                      <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
                        {formatDate(m.created_at, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
                      </TableCell>
                      <TableCell>
                        <span className="text-sm font-medium">
                          {m.inventory_items?.name ?? '—'}
                        </span>
                      </TableCell>
                      <TableCell className="text-right">
                        <span
                          className={`inline-flex items-center gap-0.5 text-sm font-semibold tabular-nums ${
                            isPositive ? 'text-foreground' : 'text-destructive'
                          }`}
                        >
                          {isPositive ? (
                            <ArrowUp className="h-3 w-3" />
                          ) : (
                            <ArrowDown className="h-3 w-3" />
                          )}
                          {isPositive ? '+' : ''}
                          {m.qty_delta} {m.inventory_items?.unit ?? ''}
                        </span>
                      </TableCell>
                      <TableCell className="text-right text-sm tabular-nums text-muted-foreground">
                        {m.qty_after} {m.inventory_items?.unit ?? ''}
                      </TableCell>
                      <TableCell>
                        <span
                          className={`inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-medium ${REASON_COLORS[m.reason]}`}
                        >
                          {REASON_LABELS[m.reason]}
                        </span>
                      </TableCell>
                      {/* Source column — derived, Stone tag */}
                      <TableCell>
                        <span className="inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-medium bg-muted text-[color:var(--color-stone)] border border-[color:var(--color-stone)]/30">
                          {source}
                        </span>
                      </TableCell>
                      <TableCell className="text-xs text-muted-foreground">
                        {m.profiles?.full_name ?? '—'}
                      </TableCell>
                      <TableCell className="max-w-[180px]">
                        {m.notes ? (
                          <span className="text-xs text-muted-foreground truncate block">
                            {m.notes}
                          </span>
                        ) : (
                          <span className="text-xs text-muted-foreground/40">—</span>
                        )}
                      </TableCell>
                    </TableRow>
                  )
                })}
              </TableBody>
            </Table>
          </div>

          {/* Pagination */}
          {total > PAGE_SIZE && (
            <div className="flex items-center justify-between">
              <p className="text-xs text-muted-foreground">
                Showing {page * PAGE_SIZE + 1}–{Math.min((page + 1) * PAGE_SIZE, total)} of {total}
              </p>
              <div className="flex gap-1">
                <Button
                  variant="outline"
                  size="icon"
                  className="h-7 w-7"
                  disabled={!hasPrev}
                  onClick={() => setPage((p) => p - 1)}
                >
                  <ChevronLeft className="h-3.5 w-3.5" />
                </Button>
                <Button
                  variant="outline"
                  size="icon"
                  className="h-7 w-7"
                  disabled={!hasNext}
                  onClick={() => setPage((p) => p + 1)}
                >
                  <ChevronRight className="h-3.5 w-3.5" />
                </Button>
              </div>
            </div>
          )}
        </>
      )}
    </div>
  )
}
